242	    }
243	
244	    protected Set<Pet> getPetsInternal() {
245	        if (this.pets == null) {
246	            this.pets = new HashSet<>();
247	        }
248	        return this.pets;
249	    }
250	
251	    protected void setPetsInternal(Set<Pet> pets) {
252	        this.pets = pets;
253	    }
254	
255	    public List<Pet> getPets() {
256	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
257	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
258	        return Collections.unmodifiableList(sortedPets);
259	    }
260	
261	    public void setPets(List<Pet> pets) {
262	        this.pets = new HashSet<>(pets);
263	    }
264	
265	    public void addPet(Pet pet) {
266	        getPetsInternal().add(pet);
267	        pet.setOwner(this);
268	    }
269	
270	    /**
271	     * Return the Pet with the given name, or null if none found for this Owner.
272	     *
273	     * @param name to test
274	     * @return true if pet name is already in use
275	     */
276	    public Pet getPet(String name) {
277	        return getPet(name, false);
278	    }
279	
280	    /**
281	     * Return the Pet with the given name, or null if none found for this Owner.
282	     *
283	     * @param name to test
284	     * @return true if pet name is already in use
285	     */
286	    public Pet getPet(String name, boolean ignoreNew) {
287	        name = name.toLowerCase();
288	        for (Pet pet : getPetsInternal()) {
289	            if (!ignoreNew || !pet.isNew()) {
290	                String compName = pet.getName();
291	                compName = compName.toLowerCase();
292	                if (compName.equals(name)) {
293	                    return pet;
294	                }
295	            }
296	        }
297	        return null;
298	    }
299	
300	    public Pet getPet(Integer petId) {
301	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
302	    }
303	
304	    @Override
305	    public String toString() {
306	        return new ToStringCreator(this)
307	
308	            .append("id", this.getId())
309	            .append("new", this.isNew())
310	            .append("lastName", this.getLastName())
311	            .append("firstName", this.getFirstName())
312	            .append("address", this.address)
313	            .append("city", this.city)
314	            .append("telephone", this.telephone)
315	            .append("email", this.email)
316	            .toString();
317	    }
318	}
