2	
3	import java.util.function.Supplier;
4	
5	import org.springframework.dao.EmptyResultDataAccessException;
6	import org.springframework.orm.ObjectRetrievalFailureException;
7	import org.springframework.samples.petclinic.rest.escalation.NotFoundException;
8	
9	/**
10	 * Shared exception-translation for Load functions: the jdbc/jpa/spring-data-jpa repository
11	 * implementations all signal "not found" by throwing rather than returning null (see
12	 * ObjectRetrievalFailureException / EmptyResultDataAccessException), so every Load function
13	 * needs the same translation to NotFoundException.
14	 */
15	public final class Lookups {
16	
17	    private Lookups() {
18	    }
19	
20	    public static <T> T findOrNotFound(Supplier<T> supplier, String notFoundMessage) throws NotFoundException {
21	        try {
22	            T result = supplier.get();
23	            if (result == null) {
24	                throw new NotFoundException(notFoundMessage);
25	            }
26	            return result;
27	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
28	            throw new NotFoundException(notFoundMessage);
29	        }
30	    }
31	}
