1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Create-time uniqueness guard for {@code POST /owners}. It rejects a request with a 409 via
10	 * {@link DuplicateIdentityException} in two cases:
11	 *
12	 * <ul>
13	 *   <li><b>Household duplicate.</b> A household is keyed on {@code (lastName, postcode)} (see
14	 *       {@link OwnerHousehold}), so an owner sharing an existing owner's last name and postcode is
15	 *       the same household and is rejected — <em>unless</em> the request sets {@code sharesHousehold},
16	 *       which bypasses this block so the owner is created as a declared household member.</li>
17	 *   <li><b>Exact identity duplicate.</b> A request whose whole {@link OwnerIdentity identityKey}
18	 *       (normalised telephone, email and household together) equals an existing owner's is rejected
19	 *       regardless of {@code sharesHousehold} — a genuinely identical owner is always a duplicate.</li>
20	 * </ul>
21	 *
22	 * <p>The household id is derived from {@code (lastName, postcode)} for both the request and each
23	 * existing owner, so the comparison is independent of any stored id. Runs after
24	 * {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail} (so the request's telephone and
25	 * email are in their stored, canonical forms) and before {@link BuildOwner}.
26	 */
27	public class CheckOwnerIdentityUnique {
28	
29	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
30	            throws DuplicateIdentityException {
31	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
32	        String householdId = OwnerHousehold.deriveId(request);
33	        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(), householdId);
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (!sharesHousehold && householdId != null
36	                    && householdId.equals(OwnerHousehold.deriveId(existing))) {
37	                throw new DuplicateIdentityException(identityKey);
38	            }
39	            if (identityKey.equals(OwnerIdentity.of(existing))) {
40	                throw new DuplicateIdentityException(identityKey);
41	            }
42	        }
43	    }
44	}
