30	            existing.add(other.getCustomerCode());
31	        }
32	        if (!existing.contains(base)) {
33	            return;
34	        }
35	        int n = 2;
36	        String candidate;
37	        do {
38	            candidate = OwnerCustomerCode.withSuffix(base, n);
39	            n++;
40	        }
41	        while (existing.contains(candidate));
