3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Single source of truth for the owner address normalisation rule used across the
8	 * {@code POST /owners} pipeline: an address is canonicalised by trimming, collapsing internal
9	 * whitespace to single spaces, upper-casing, and expanding common abbreviations as whole words
10	 * ({@code ST}→{@code STREET}, {@code RD}→{@code ROAD}, {@code AVE}→{@code AVENUE}). So
11	 * {@code "  12  main  st "} canonicalises to {@code "12 MAIN STREET"} and {@code "7 elm ave"} to
12	 * {@code "7 ELM AVENUE"}.
13	 *
14	 * <p>The class also owns the <em>composition</em> rule for the structured address form (see
15	 * {@link #compose(String, String)}): the single stored/returned/compared value is the normalized
16	 * {@code addressLine1} with the normalized {@code addressLine2} appended after a single space when
17	 * present.
18	 *
19	 * <p>Centralised here (rather than inlined) so its one consumer has a single definition to agree
20	 * on: {@link ValidateOwnerFields} stores the canonical value — flat or composed — and rejects a
21	 * value that is blank once normalised.
22	 */
23	final class OwnerAddress {
24	
25	    /** Whole-word abbreviations expanded during normalisation. */
26	    private static final Map<String, String> ABBREVIATIONS = Map.of(
27	            "ST", "STREET",
28	            "RD", "ROAD",
29	            "AVE", "AVENUE");
30	
31	    private OwnerAddress() {
32	    }
33	
34	    /**
35	     * The stored/returned/compared form: trimmed, internal whitespace collapsed to single
36	     * spaces, upper-cased, with common abbreviations expanded as whole words. Returns an empty
37	     * string for a null or whitespace-only input.
38	     */
39	    static String normalize(String address) {
40	        if (address == null) {
41	            return "";
42	        }
43	        String trimmed = address.trim();
44	        if (trimmed.isEmpty()) {
45	            return "";
46	        }
47	        String[] tokens = trimmed.toUpperCase(Locale.ROOT).split("\\s+");
48	        StringBuilder sb = new StringBuilder();
49	        for (String token : tokens) {
50	            if (sb.length() > 0) {
51	                sb.append(' ');
52	            }
53	            sb.append(ABBREVIATIONS.getOrDefault(token, token));
54	        }
55	        return sb.toString();
56	    }
57	
58	    /**
59	     * The stored/returned/compared form of a structured address: the {@link #normalize(String)
60	     * normalized} {@code line1} with a single space and the normalized {@code line2} appended when
61	     * {@code line2} is non-blank once normalised. Returns just the normalized {@code line1} when
62	     * there is no second line. Normalisation is idempotent, so already-normalised inputs compose to
63	     * the same result.
64	     */
65	    static String compose(String line1, String line2) {
66	        String normalizedLine1 = normalize(line1);
67	        String normalizedLine2 = normalize(line2);
68	        return normalizedLine2.isEmpty() ? normalizedLine1
69	                : normalizedLine1 + " " + normalizedLine2;
70	    }
71	}
