7	 * pipeline. The region is derived from the <em>postcode range</em> first (NSW 2000-2099,
8	 * VIC 3000-3099, QLD 4000-4099), falling back to a fixed city-to-region table
9	 * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) only when the postcode is absent or in no
10	 * known range; any other input has no known region. Resolving by postcode first returns the same
11	 * region for the known cities but disambiguates cities that share a name.
12	 *
13	 * <p>Centralised here (as {@link OwnerAddress} is for address normalisation) so the read-time and
14	 * write-time sides of the rule cannot drift: {@code OwnerMapper.locality} derives the returned
15	 * {@code locality} from it, and {@link ValidateOwnerPostcode} uses it to decide which region's
16	 * postcode range a supplied postcode must fall within.
17	 */
18	public final class OwnerLocality {
19	
20	    /** City -> canonical region. Anything not listed has no known region. */
21	    private static final Map<String, String> CITY_REGION = Map.of(
22	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
23	
24	    /** Region -> inclusive 4-digit postcode range {low, high}. */
25	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
26	            "NSW", new int[] {2000, 2099},
27	            "VIC", new int[] {3000, 3099},
28	            "QLD", new int[] {4000, 4099});
29	
30	    /** Region -> IANA timezone name. Anything not listed has no known timezone. */
31	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
32	            "NSW", "Australia/Sydney",
33	            "VIC", "Australia/Melbourne",
34	            "QLD", "Australia/Brisbane");
35	
36	    private OwnerLocality() {
37	    }
38	
39	    /**
40	     * The canonical region for the given city, or {@code null} when the city is not in the
41	     * table (no known region).
42	     */
43	    public static String regionForCity(String city) {
44	        return city == null ? null : CITY_REGION.get(city);
45	    }
46	
47	    /**
48	     * The canonical region whose postcode range contains the given postcode, or {@code null} when
49	     * the postcode is absent, not four digits, or in no known range.
