53	            return null;
54	        }
55	        int value = Integer.parseInt(postcode);
56	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
57	            int[] range = entry.getValue();
58	            if (value >= range[0] && value <= range[1]) {
59	                return entry.getKey();
60	            }
61	        }
62	        return null;
63	    }
64	
65	    /** The region's inclusive 4-digit postcode range {low, high}, or {@code null} when none. */
66	    public static int[] postcodeRange(String region) {
67	        return region == null ? null : REGION_POSTCODES.get(region);
68	    }
69	
70	    /**
71	     * The region's IANA timezone name (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
72	     * QLD-&gt;Australia/Brisbane), or {@code null} when the region is null or has no known timezone.
73	     */
74	    public static String timezoneForRegion(String region) {
75	        return region == null ? null : REGION_TIMEZONE.get(region);
76	    }
77	
78	    /**
79	     * The owner's canonical region, preferring the postcode's region and falling back to the
80	     * city-to-region table when the postcode is absent or in no known range. Returns {@code null}
81	     * when neither yields a known region. Callers that need a display sentinel map {@code null}
