2	
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	
6	/**
7	 * Single source of truth for the owner telephone normalisation rule used across the
8	 * {@code POST /owners} pipeline: a telephone is canonicalised to E.164 form. Both
9	 * {@link NormalizeOwnerTelephone} (which stores the canonical value and rejects an input that
10	 * cannot form one) and {@link OwnerIdentity} (which folds the canonical value into the identity
11	 * key) must agree on this definition, so it lives here rather than being re-implemented at each
12	 * site.
13	 *
14	 * <p>The rule: strip spaces, dashes and brackets; keep a leading {@code '+'} and country code
15	 * when present, otherwise assume country code {@code +61} and drop a single leading {@code '0'}
16	 * from the national digits; the result must be a {@code '+'} followed by 8 to 15 digits. So
17	 * {@code "0412 345 678"} canonicalises to {@code "+61412345678"} and {@code "+64 21 123 456"}
18	 * to {@code "+6421123456"}.
19	 *
20	 * <p>In addition, where the country code has a known fixed national-number length, the national
21	 * part (the digits after the country code) must have exactly that length: {@code +61} requires
22	 * 9 national digits and {@code +1} requires 10. A number whose national part is the wrong length
23	 * for its country is not a valid E.164 number here and is rejected. Country codes without a
24	 * listed rule keep only the general 8-to-15-digit total check.
25	 */
26	public final class OwnerTelephone {
27	
28	    /**
29	     * Country code (without the leading {@code '+'}) to its required national-number length.
30	     * Ordered longest-prefix-first so a number is matched against {@code 61} before {@code 1}.
31	     */
32	    private static final Map<String, Integer> NATIONAL_LENGTHS = new LinkedHashMap<>();
33	
34	    static {
35	        NATIONAL_LENGTHS.put("61", 9);
36	        NATIONAL_LENGTHS.put("1", 10);
37	    }
38	
39	    private OwnerTelephone() {
40	    }
41	
42	    /**
43	     * Canonicalise {@code telephone} to E.164 form, or return {@code null} when it cannot form a
44	     * valid E.164 number (null/blank input, a non-digit left after stripping separators, fewer
45	     * than 8 or more than 15 digits after the {@code '+'}, or a national part whose length is
46	     * wrong for a country code with a known fixed length — {@code +61} => 9, {@code +1} => 10).
47	     */
48	    static String toE164(String telephone) {
49	        if (telephone == null) {
50	            return null;
51	        }
52	        // Strip spaces, dashes and brackets, leaving an optional leading '+' and the digits.
53	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
54	        String digits;
55	        if (cleaned.startsWith("+")) {
56	            // Leading '+' and country code present: keep as-is.
57	            digits = cleaned.substring(1);
58	        } else {
59	            // No country code: assume +61 and drop a single leading '0' from the national digits.
60	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
61	            digits = "61" + national;
62	        }
63	        if (!digits.matches("[0-9]{8,15}")) {
64	            return null;
65	        }
66	        // Enforce the per-country national-number length where one is known.
67	        for (Map.Entry<String, Integer> rule : NATIONAL_LENGTHS.entrySet()) {
68	            String countryCode = rule.getKey();
69	            if (digits.startsWith(countryCode)) {
70	                int nationalLength = digits.length() - countryCode.length();
71	                if (nationalLength != rule.getValue()) {
72	                    return null;
73	                }
74	                break;
75	            }
76	        }
77	        return "+" + digits;
78	    }
79	
80	    /**
81	     * Best-effort canonical form of {@code telephone}: its E.164 form ({@link #toE164(String)})
82	     * when it forms one, otherwise the raw value unchanged (and the empty string when null). Used
83	     * where a stable string is needed even for a value that is not a valid E.164 number — folding
84	     * the telephone into the owner identity key ({@link OwnerIdentity}) and into the identity's
85	     * hash ({@code OwnerCustomerCode}) — so that fallback policy lives here alongside the rule it
86	     * builds on rather than being reimplemented at each site.
87	     */
88	    static String toE164OrRaw(String telephone) {
89	        String e164 = toE164(telephone);
90	        return e164 != null ? e164 : (telephone == null ? "" : telephone);
91	    }
92	
93	    /**
94	     * Human-readable form of a stored E.164 {@code telephone}: the country code, a space, then
95	     * the national digits grouped in threes (e.g. {@code "+61412345678"} => {@code "+61 412 345
96	     * 678"}). The country code is identified from {@link #NATIONAL_LENGTHS}, longest-prefix-first
97	     * (so {@code 61} matches before {@code 1}). Null in gives null out; a value that is not a
98	     * recognisable E.164 number (cannot be canonicalised, or whose country code is not one we
99	     * list) is returned unchanged, so the display is always best-effort rather than throwing.
100	     */
101	    public static String toDisplay(String telephone) {
102	        if (telephone == null) {
103	            return null;
104	        }
105	        String e164 = toE164(telephone);
106	        if (e164 == null) {
107	            return telephone;
108	        }
109	        String digits = e164.substring(1); // drop the leading '+'
110	        String countryCode = null;
111	        for (String code : NATIONAL_LENGTHS.keySet()) {
112	            if (digits.startsWith(code)) {
113	                countryCode = code;
114	                break;
115	            }
116	        }
117	        if (countryCode == null) {
118	            return e164;
119	        }
120	        String national = digits.substring(countryCode.length());
121	        StringBuilder sb = new StringBuilder("+").append(countryCode);
122	        for (int i = 0; i < national.length(); i += 3) {
123	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
124	        }
125	        return sb.toString();
126	    }
127	}
