3	import java.util.Locale;
4	import java.util.Set;
5	import java.util.regex.Pattern;
6	
7	/**
8	 * Single source of truth for the owner email rule used by the {@code POST /owners} pipeline:
9	 * email is optional, but when supplied it must be a syntactically valid address, must not use a
10	 * disposable-email domain, and is stored and returned lower-cased. Centralised here (rather than
11	 * inlined in {@link NormalizeOwnerEmail}) so the notions of "present", "valid", "disposable" and
12	 * "normalised" stay defined in one place.
13	 */
14	final class OwnerEmail {
15	
16	    /**
17	     * A pragmatic syntactic check: a non-empty local part, a single {@code @}, and a domain with
18	     * at least one dot and non-empty labels, none containing whitespace or {@code @}.
19	     */
20	    private static final Pattern VALID = Pattern.compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+$");
21	
22	    /** Disposable-email domains that are not accepted for owner registration. */
23	    private static final Set<String> DISPOSABLE_DOMAINS =
24	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
25	
26	    private OwnerEmail() {
27	    }
28	
29	    /** An email is "present" when it is non-null and not blank. */
30	    static boolean isPresent(String email) {
31	        return email != null && !email.isBlank();
32	    }
33	
34	    /** Whether the (present) value is a syntactically valid address. */
35	    static boolean isValid(String email) {
36	        return email != null && VALID.matcher(email.trim()).matches();
37	    }
38	
39	    /** Whether the (valid) value's domain is on the disposable-email blocklist. */
40	    static boolean isDisposable(String email) {
41	        String normalized = normalize(email);
42	        int at = normalized.lastIndexOf('@');
43	        if (at < 0) {
44	            return false;
45	        }
46	        return DISPOSABLE_DOMAINS.contains(normalized.substring(at + 1));
47	    }
48	
49	    /** The stored/returned form: trimmed and lower-cased. */
50	    static String normalize(String email) {
51	        return email.trim().toLowerCase(Locale.ROOT);
52	    }
53	}
