2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Single source of truth for an owner's {@code customerCode}: the region-and-hash identity every
11	 * other derived owner value flows from. It owns both sides of the {@code <REGION>-<HASH8>} format
12	 * so the write-time side ({@link AssignCustomerCode}, which constructs it) and the read-time side
13	 * ({@code OwnerMapper.locality}, which recovers the region from it) cannot drift — mirroring how
14	 * {@link OwnerIdentity}, {@link OwnerTelephone} and {@link OwnerLocality} centralise their rules.
15	 *
16	 * <p>The format is {@code <REGION>-<HASH8>} where:
17	 * <ul>
18	 *   <li>{@code REGION} is the owner's region ({@link #regionFor}): the postcode's region, falling
19	 *       back to the city-to-region table, and {@link #UNKNOWN_REGION} when neither resolves;</li>
20	 *   <li>{@code HASH8} is the first 8 upper-case hex characters of SHA-256 over the owner's
21	 *       canonical telephone ({@link OwnerTelephone#toE164OrRaw(String)}) concatenated with its
22	 *       last name (e.g. {@code NSW-1A2B3C4D}).</li>
23	 * </ul>
24	 *
25	 * <p>Because {@code REGION} is a fixed set of letters ({@code NSW}/{@code VIC}/{@code QLD}/
26	 * {@code UNKNOWN}) and {@code HASH8} is hex, neither contains a {@code '-'}, so the first
27	 * {@code '-'} cleanly separates the two halves for {@link #regionOf}.
28	 */
29	public final class OwnerCustomerCode {
30	
31	    /** Region sentinel used when neither the postcode nor the city resolves to a known region. */
32	    public static final String UNKNOWN_REGION = "UNKNOWN";
33	
34	    private static final char SEPARATOR = '-';
35	
36	    private OwnerCustomerCode() {
37	    }
38	
39	    /** The region-and-hash {@code customerCode} for the owner's current fields. */
40	    public static String of(Owner owner) {
41	        return regionFor(owner) + SEPARATOR + hash8(OwnerTelephone.toE164OrRaw(owner.getTelephone())
42	                + owner.getLastName());
43	    }
44	
45	    /**
46	     * The owner's region for identity and display: the postcode/city region (see
47	     * {@link OwnerLocality#regionFor}), or {@link #UNKNOWN_REGION} when neither resolves.
48	     */
49	    public static String regionFor(Owner owner) {
50	        String region = OwnerLocality.regionFor(owner.getPostcode(), owner.getCity());
51	        return region != null ? region : UNKNOWN_REGION;
52	    }
53	
54	    /**
55	     * A de-duplicated variant of {@code base}, formed by appending {@code -<n>} (e.g.
56	     * {@code NSW-1A2B3C4D} with {@code n == 2} becomes {@code NSW-1A2B3C4D-2}). Used when the
57	     * derived {@code customerCode} collides with an existing owner's: the caller picks the smallest
58	     * {@code n} of 2 or more that is free. Keeping the suffix spelling here, next to {@link #of} and
59	     * {@link #regionOf}, keeps this class the single authority for the {@code customerCode} format —
60	     * the {@code REGION} prefix is unchanged, so {@link #regionOf} still reads the region from the
61	     * first {@code '-'}.
62	     */
63	    public static String withSuffix(String base, int n) {
64	        return base + SEPARATOR + n;
65	    }
66	
67	    /**
68	     * The {@code REGION} half of a {@code customerCode} (the text before the first {@code '-'}), or
69	     * {@code null} when {@code customerCode} is null or carries no region prefix.
70	     */
71	    public static String regionOf(String customerCode) {
72	        if (customerCode == null) {
73	            return null;
74	        }
75	        int sep = customerCode.indexOf(SEPARATOR);
76	        return sep > 0 ? customerCode.substring(0, sep) : null;
77	    }
78	
79	    /** The first 8 upper-case hex characters (4 bytes) of SHA-256 over {@code value}. */
80	    private static String hash8(String value) {
81	        try {
82	            byte[] digest = MessageDigest.getInstance("SHA-256")
83	                .digest(value.getBytes(StandardCharsets.UTF_8));
84	            StringBuilder sb = new StringBuilder(8);
85	            for (int i = 0; i < 4; i++) {
86	                sb.append(String.format("%02X", digest[i]));
87	            }
88	            return sb.toString();
89	        }
90	        catch (NoSuchAlgorithmException ex) {
91	            throw new IllegalStateException("SHA-256 not available", ex);
92	        }
93	    }
94	}
