3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Single source of truth for the business-day rule on an owner's registration date: the
11	 * effective registration date must fall on a business day, so a Saturday or Sunday rolls
12	 * forward to the following Monday. A date that is already a weekday is returned unchanged.
13	 *
14	 * <p>Centralised here so every site agrees on one definition: {@link BuildOwner} stores the
15	 * adjusted date on the owner (and everything derived from it, such as the membership number's
16	 * year segment in {@link AssignMembershipNumber}, then uses the adjusted value), while
17	 * {@link CheckDailyOwnerLimit} counts existing owners against the same adjusted business day.
18	 */
19	final class BusinessDay {
20	
21	    private BusinessDay() {
22	    }
23	
24	    /**
25	     * Rolls {@code date} forward to the next business day: a Saturday or Sunday advances to the
26	     * following Monday; a weekday is returned unchanged.
27	     */
28	    static LocalDate rollForward(LocalDate date) {
29	        LocalDate rolled = date;
30	        while (rolled.getDayOfWeek() == DayOfWeek.SATURDAY || rolled.getDayOfWeek() == DayOfWeek.SUNDAY) {
31	            rolled = rolled.plusDays(1);
32	        }
33	        return rolled;
34	    }
35	
36	    /**
37	     * Counts existing owners whose stored {@code registrationDate} equals {@code businessDay} — the
38	     * single definition of "owners created on this business day" shared by the create-time rules
39	     * ({@link CheckDailyOwnerLimit}'s hard cap and {@link AssignBulkSignupWarning}'s flag), so they
40	     * can never drift apart. Both call this and compare the result against their own threshold.
41	     */
42	    static long countOwnersOn(LocalDate businessDay, OwnerRepository ownerRepository) {
43	        return ownerRepository.findAll().stream()
44	            .map(Owner::getRegistrationDate)
45	            .filter(businessDay::equals)
46	            .count();
47	    }
48	}
